public class CommandLineRunner_createOptions_TriageGen1Test {

    @Rule
    public TemporaryFolder tempFolder = new TemporaryFolder();

    /**
     * Since CommandLineRunner is a complex class and createOptions is protected,
     * we use a Testable subclass to access the method and manipulate the 'flags' field.
     * In a real scenario, flags would be populated by the command line arguments.
     */
    private static class TestableCommandLineRunner extends CommandLineRunner {
        public Flags flags;

        protected TestableCommandLineRunner(String[] args) {
            super(args);
            this.flags = new Flags();
            // Initialize mandatory flags to avoid NullPointerException
            this.flags.compilationLevel = CompilationLevel.SIMPLE_OPTIMIZATIONS;
            this.flags.warningLevel = WarningLevel.QUIET;
            this.flags.translationsFile = "";
        }

        @Override
        public CompilerOptions createOptions() {
            // We must bypass the actual logic of the parent if it tries to parse args 
            // and instead use our injected flags. Since we can't easily inject into 
            // the real private 'flags' field of the parent via reflection safely in all environments,
            // this test assumes the method uses the instance variable 'flags'.
            return super.createOptions();
        }
    }

    @Test
    public void testCreateOptions_JqueryPrimitivesTrue() {
        TestableCommandLineRunner runner = new TestableCommandLineRunner(new String[]{});
        runner.flags.processJqueryPrimitives = true;
        runner.flags.compilationLevel = CompilationLevel.SIMPLE_OPTIMIZATIONS;
        runner.flags.warningLevel = WarningLevel.QUIET;
        runner.flags.extraAnnotationName = Collections.singletonList("Annotation");
        runner.flags.debug = false;
        runner.flags.useTypesForOptimization = false;
        runner.flags.generateExports = true;
        runner.flags.formatting = Collections.emptyList();
        runner.flags.processClosurePrimitives = true;
        runner.flags.angularPass = true;
        runner.flags.translationsFile = "";

        CompilerOptions options = runner.createOptions();

        assertThat(options.getCodingConvention()).isInstanceOf(JqueryCodingConvention.class);
        assertThat(options.getExtraAnnotationNames()).containsExactly("Annotation");
        assertThat(options.getGenerateExports()).isTrue();
        assertThat(options.closurePass).isTrue();
        assertThat(options.jqueryPass).isFalse(); // Not ADVANCED
        assertThat(options.angularPass).isTrue();
    }

    @Test
    public void testCreateOptions_JqueryPrimitivesFalse() {
        TestableCommandLineRunner runner = new TestableCommandLineRunner(new String[]{});
        runner.flags.processJqueryPrimitives = false;
        runner.flags.compilationLevel = CompilationLevel.SIMPLE_OPTIMIZATIONS;
        runner.flags.warningLevel = WarningLevel.QUIET;
        runner.flags.extraAnnotationName = Collections.emptyList();
        runner.flags.debug = false;
        runner.flags.useTypesForOptimization = false;
        runner.flags.generateExports = false;
        runner.flags.formatting = Collections.emptyList();
        runner.flags.processClosurePrimitives = false;
        runner.flags.angularPass = false;
        runner.flags.translationsFile = "";

        CompilerOptions options = runner.createOptions();

        assertThat(options.getCodingConvention()).isInstanceOf(ClosureCodingConvention.class);
        assertThat(options.closurePass).isFalse();
        assertThat(options.jqueryPass).isFalse();
    }

    @Test
    public void testCreateOptions_AdvancedOptimizationWithJquery() {
        TestableCommandLineRunner runner = new TestableCommandLineRunner(new String[]{});
        runner.flags.processJqueryPrimitives = true;
        runner.flags.compilationLevel = CompilationLevel.ADVANCED_OPTIMIZATIONS;
        runner.flags.warningLevel = WarningLevel.QUIET;
        runner.flags.extraAnnotationName = Collections.emptyList();
        runner.flags.debug = true;
        runner.flags.useTypesForOptimization = true;
        runner.flags.generateExports = false;
        runner.flags.formatting = Collections.emptyList();
        runner.flags.processClosurePrimitives = true;
        runner.flags.angularPass = false;
        runner.flags.translationsFile = "";

        CompilerOptions options = runner.createOptions();

        assertThat(options.jqueryPass).isTrue();
        assertThat(options.messageBundle).isInstanceOf(EmptyMessageBundle.class);
    }

    @Test
    public void testCreateOptions_AdvancedWithTranslationsFile() throws IOException {
        Path tempFile = tempFolder.newFile("translations.xtb");
        try (FileWriter writer = new FileWriter(tempFile.toFile())) {
            writer.write("dummy content");
        }

        TestableCommandLineRunner runner = new TestableCommandLineRunner(new String[]{});
        runner.flags.compilationLevel = CompilationLevel.ADVANCED_OPTIMIZATIONS;
        runner.flags.warningLevel = WarningLevel.QUIET;
        runner.flags.translationsFile = tempFile.toString();
        runner.flags.translationsProject = "test-project";
        runner.flags.processJqueryPrimitives = false;
        runner.flags.extraAnnotationName = Collections.emptyList();
        runner.flags.debug = false;
        runner.flags.useTypesForOptimization = false;
        runner.flags.generateExports = false;
        runner.flags.formatting = Collections.emptyList();
        runner.flags.processClosurePrimitives = false;
        runner.flags.angularPass = false;

        CompilerOptions options = runner.createOptions();

        assertThat(options.messageBundle).isNotNull();
        // Verification of specific bundle type depends on implementation of XtbMessageBundle
    }

    @Test
    public void testCreateOptions_TranslationsFileError() throws IOException {
        // Create a directory instead of a file to trigger IOException on FileInputStream
        File dir = tempFolder.newFolder("not-a-file");

        TestableCommandLineRunner runner = new TestableCommandLineRunner(new String[]{});
        runner.flags.compilationLevel = CompilationLevel.SIMPLE_OPTIMIZATIONS;
        runner.flags.warningLevel = WarningLevel.QUIET;
        runner.flags.translationsFile = dir.getAbsolutePath();
        runner.flags.extraAnnotationName = Collections.emptyList();
        runner.flags.processJqueryPrimitives = false;
        runner.flags.debug = false;
        runner.flags.useTypesForOptimization = false;
        runner.flags.generateExports = false;
        runner.flags.formatting = Collections.emptyList();
        runner.flags.processClosurePrimitives = false;
        runner.flags.angularPass = false;

        assertThrows(RuntimeException.class, () -> runner.createOptions());
    }

    @Test
    public void testCreateOptions_FormattingOptions() {
        TestableCommandLineRunner runner = new TestableCommandLineRunner(new String[]{});
        runner.flags.compilationLevel = CompilationLevel.SIMPLE_OPTIMIZATIONS;
        runner.flags.warningLevel = WarningLevel.QUIET;
        runner.flags.extraAnnotationName = Collections.emptyList();
        runner.flags.processJqueryPrimitives = false;
        runner.flags.translationsFile = "";

        // Mocking a formatting option
        FormattingOption mockFormat = new FormattingOption() {
            @Override
            public void applyToOptions(CompilerOptions options) {
                options.setGenerateExports(true);
            }
        };
        runner.flags.formatting = Collections.singletonList(mockFormat);
        runner.flags.generateExports = false;

        CompilerOptions options = runner.createOptions();
        assertThat(options.getGenerateExports()).isTrue();
    }
}
